#define iterations 12
#define formuparam 0.53

#define volsteps 20
#define stepsize 0.1

#define zoom   0.800
#define tile   0.850
#define speed  0.00

#define brightness 0.0015
#define darkmatter 0.300
#define distfading 0.730
#define saturation 0.850

#define max4(A,B,C,D) max(max(A,B),max(C,D))
#define max3(A,B,C) max(max(A,B),C)

#define twizzle(p) \
    if ( p.y >= max(p.x,p.z) ) p = p.yzx; \
    else if ( p.z >= max(p.x,p.y) ) p = p.zxy;

float sdTetrahedron(vec3 p,float r) {
    twizzle(p) // abs(p) here makes something else nice
    return max3( /*-p.x+p.y+p.z,*/ p.x-p.y+p.z, p.x+p.y-p.z, -p.x-p.y-p.z)/sqrt(3.) - r;
}

float sdCube(vec3 p,float r) {
    p = abs(p); twizzle(p) // so similar compiler might generate same code...
    return p.x - r;
    //return max3(p.x,p.y,p.z) - r;
}

float sdOctahedron(vec3 p,float r) {
    p = abs(p); // twizzle(p) no benifit here
    return (p.x+p.y+p.z)/sqrt(3.) - r;
}

#define PHI 1.6180339887

float sdDodecahedron(vec3 p,float r) {
    p = abs(p); twizzle(p)
    return max( /* p.y+p.z*PHI, */ p.z+p.x*PHI, p.x+p.y*PHI )/sqrt(2.+PHI) - r;
}

float sdIcosahedron(vec3 p,float r) {
    p = abs(p); twizzle(p)
    return max3( p.x+p.y+p.z, /* p.y/PHI+p.z*PHI, */ p.z/PHI+p.x*PHI, p.x/PHI+p.y*PHI )/sqrt(3.) - r;
}    

// Circumscribed sphere radius ratio to Inscribed sphere radius (thanks spalmer)
#define CircSphTetrahedron  (1./3.)
#define CircSphCube         sqrt(1./3.)
#define CircSphOctahedron   sqrt(1./3.)
#define CircSphDodecahedron sqrt(1./PHI)
#define CircSphIcosahedron  sqrt(1./PHI)

#define ROT2(ANG) mat2(cos(ANG),sin(ANG),-sin(ANG),cos(ANG))

#define PI 3.141592653589793
#define TAU (2.*PI)

vec3 Spin(float tim,vec3 p) {
tim=0.;
   tim += iTime*1.;
   p.xz *= ROT2(tim*.75+iMouse.x*TAU/iResolution.x);
   p.yz *= ROT2(tim*.25+iMouse.y*TAU/iResolution.y);
   p.yx *= ROT2(tim*.5);
   return p;
}

#define sin1(X) (.5+.5*sin(X))
#define sinab(X,A,B) (sin1(X)*(B-A)+A)

#define min3(A,B,C) min(min(A,B),C)

bool hide;
int ccol;
float off;
vec3 Split(vec3 p) {
   vec3 save = p;
   p = abs(p);


   hide = p.y < 0. || p.y < 0. || p.z < 0.;
   p = max(p,vec3(0));
   ccol = 0;
   if ( off > 0. && ! hide ) {
     if ( p.x > max(p.y,p.z) )
       ccol = 1;


     }
   return p * sign(save);
}

#define T(SDF) if ( (tmp = SDF) < hit.x ) ccol2=ccol, hide2=hide, hit = vec2(tmp,clr); clr += 1.;

bool hide2;
int ccol2;
vec2 Dist(vec3 pt) {
    vec2 hit = vec2(100000,0);
    float tmp, clr = 0.;

    float SZ=6.;

    clr = 0.;


    T(sdIcosahedron( Split(Spin(2.,pt-vec3(0,-0,9))),SZ*CircSphIcosahedron));

    return hit;
}

vec4 March(vec3 beg,vec3 dir) {
    float dist = 0.;
    vec3 pos;
    #define LIMIT 100
    for ( int stps = 0; stps <= LIMIT; ++stps ) {
        pos = beg + dir * dist;
        vec2 obj = Dist( pos );
        dist += obj.x;

    }
    return vec4( pos, 90. );
}

vec3 Normal(vec3 pt) {
    float delta = .4;
    vec3 norm = Dist(pt).x - vec3(
        Dist(pt-vec3(delta, 0., 0.)).x, 
        Dist(pt-vec3( 0.,delta, 0.)).x, 
        Dist(pt-vec3( 0., 0.,delta)).x );
    return normalize( norm );
}

float pow2n(float i,int n)
{
  while ( n-- > 0 ) i *= i;
  return i;
}
#define NUM_LAYERS 8.
#define TAU2 6.28318
#define PI2 3.141592
#define Velocity .025 //modified value to increse or decrease speed, negative value travel backwards
#define StarGlow 0.025
#define StarSize 02.
#define CanvasView 20.


float Star(vec2 uv, float flare){
    float d = length(uv);
  	float m = sin(StarGlow*1.2)/d;  
    float rays = max(0., .5-abs(uv.x*uv.y*1000.)); 
    m += (rays*flare)*2.;
    m *= smoothstep(1., .1, d);
    return m;
}

float Hash21(vec2 p){
    p = fract(p*vec2(123.34, 456.21));
    p += dot(p, p+45.32);
    return fract(p.x*p.y);
}
vec3 StarLayer(vec2 uv){
    vec3 col = vec3(0);
    vec2 gv = fract(uv);
    vec2 id = floor(uv);
    for(int y=-1;y<=1;y++){
        for(int x=-1; x<=1; x++){
            vec2 offs = vec2(x,y);
            float n = Hash21(id+offs);
            float size = fract(n);
            float star = Star(gv-offs-vec2(n, fract(n*34.))+.5, smoothstep(.1,.9,size)*.46);
            vec3 color = sin(vec3(.2,.3,.9)*fract(n*2345.2)*TAU)*.25+.75;
            color = color*vec3(.9,.59,.9+size);
            star *= sin(iTime*.6+n*TAU)*.5+.5;
            col += star*size*color;
        }
    }
    return col;
}


void mainVR( out vec4 fragColor, in vec2 fragCoord, in vec3 ro, in vec3 rd )
{
	//get coords and direction
	vec3 dir=rd;
	vec3 from=ro;

	//volumetric rendering
	float s=0.1,fade=1.;
	vec3 v=vec3(0.);
	for (int r=0; r<volsteps; r++) {
		vec3 p=from+s*dir*.5;
		p = abs(vec3(tile)-mod(p,vec3(tile*2.))); // tiling fold
		float pa,a=pa=0.;
		for (int i=0; i<iterations; i++) { 
			p=abs(p)/dot(p,p)-formuparam;
            p.xy*=mat2(cos(iTime*0.05),sin(iTime*0.05),-sin(iTime*0.05),cos(iTime*0.05) );// the magic formula
			a+=abs(length(p)-pa); // absolute sum of average change
			pa=length(p);
		}
		float dm=max(0.,darkmatter-a*a*.001); //dark matter
		a*=a*a; // add contrast
		if (r>6) fade*=1.2-dm; // dark matter, don't render near
		//v+=vec3(dm,dm*.5,0.);
		v+=fade;
		v+=vec3(s,s*s,s*s*s*s)*a*brightness*fade; // coloring based on distance
		fade*=distfading; // distance fading
		s+=stepsize;
	}
	v=mix(vec3(length(v)),v,saturation); //color adjust
	fragColor = vec4(v*.031,.1);	
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	//get coords and direction
	vec2 uv=fragCoord.xy/iResolution.xy-.5;
	uv.y*=iResolution.y/iResolution.x;
	vec3 dir=vec3(uv*zoom,1.);
	float time=iTime*speed+.25;


 vec2 R = iResolution.xy;
 vec2 U = fragCoord;

 vec4 O = fragColor;
    vec2 uv2 = (U+U-R) / min(R.x,R.y);  // -1 ... +1
    uv2 /= 5.;

    vec3 cam = vec3( 0, 0, -74.);
    vec3 camdir = normalize( vec3( uv2, 3. ) );

    vec4 hit = March( cam, camdir );
    vec3 norm = Normal(hit.xyz);

    vec3 light = vec3( 0, 10, -10 );
    vec3 dir2 = normalize( light - hit.xyz );
    float difu = dot( norm, dir2 );

    difu = .5 + .5*difu;

    #define col4(X) ( .5 + .3 * sin( vec4(0,21,23,0) + (X) ) )
    O = sqrt( col4(hit.w*.4) );
    if (ccol2==1) O=mix(O,vec4(1,0,0,1),off*.15); else
    if (ccol2==2) O=mix(O,vec4(0,1,0,1),off*.15); else
    if (ccol2==3) O=mix(O,vec4(0,0,1,1),off*.15);
    O *= difu + pow2n(difu,29);




	vec2 M = vec2(0);
    M -= vec2(M.x+sin(iTime*0.22), M.y-cos(iTime*0.22));
    M +=(iMouse.xy-iResolution.xy*.5)/iResolution.y;
    float t = iTime*Velocity; 
    vec3 col = vec3(0);  
    for(float i=0.; i<1.; i+=1./NUM_LAYERS){
        float depth = fract(i+t);
        float scale = mix(CanvasView, .5, depth);
        float fade = depth*smoothstep(1.,.9,depth);
        col += StarLayer(uv*scale+i*453.2-iTime*.05+M)*fade;}   
	vec3 from=vec3(1.,.5,0.5)*col;

	mainVR(fragColor, fragCoord, from, dir);	
    fragColor+=vec4(col*O.xyz,1.);
}
